CREATE TYPE "Role" AS ENUM ('CUSTOMER', 'ADMIN');
CREATE TYPE "OrderStatus" AS ENUM ('PENDING', 'CONFIRMED', 'SHIPPED', 'DELIVERED', 'CANCELLED');
CREATE TYPE "InventoryReason" AS ENUM ('CHECKOUT', 'CANCELLATION', 'ADMIN_ADJUSTMENT');
CREATE TABLE "User" ("id" UUID PRIMARY KEY, "name" VARCHAR(100) NOT NULL, "email" VARCHAR(255) NOT NULL UNIQUE, "passwordHash" TEXT NOT NULL, "role" "Role" NOT NULL DEFAULT 'CUSTOMER', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Session" ("id" UUID PRIMARY KEY, "userId" UUID NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "tokenHash" CHAR(64) NOT NULL UNIQUE, "csrfHash" CHAR(64) NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Category" ("id" UUID PRIMARY KEY, "name" VARCHAR(80) NOT NULL UNIQUE, "slug" VARCHAR(100) NOT NULL UNIQUE, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Product" ("id" UUID PRIMARY KEY, "name" VARCHAR(160) NOT NULL, "slug" VARCHAR(180) NOT NULL UNIQUE, "description" TEXT NOT NULL, "sku" VARCHAR(64) NOT NULL UNIQUE, "price" INTEGER NOT NULL CHECK ("price" >= 0), "stock" INTEGER NOT NULL DEFAULT 0 CHECK ("stock" >= 0), "imageUrl" TEXT NOT NULL, "isActive" BOOLEAN NOT NULL DEFAULT true, "categoryId" UUID NOT NULL REFERENCES "Category"("id") ON DELETE RESTRICT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "CartItem" ("id" UUID PRIMARY KEY, "userId" UUID NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "productId" UUID NOT NULL REFERENCES "Product"("id") ON DELETE CASCADE, "quantity" INTEGER NOT NULL CHECK ("quantity" > 0), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, UNIQUE("userId", "productId"));
CREATE TABLE "Order" ("id" UUID PRIMARY KEY, "userId" UUID NOT NULL REFERENCES "User"("id") ON DELETE RESTRICT, "status" "OrderStatus" NOT NULL DEFAULT 'PENDING', "totalAmount" INTEGER NOT NULL CHECK ("totalAmount" >= 0), "idempotencyKey" VARCHAR(128) NOT NULL, "idempotencyHash" CHAR(64) NOT NULL, "shippingAddress" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, UNIQUE("userId", "idempotencyKey"));
CREATE TABLE "OrderItem" ("id" UUID PRIMARY KEY, "orderId" UUID NOT NULL REFERENCES "Order"("id") ON DELETE CASCADE, "productId" UUID NOT NULL REFERENCES "Product"("id") ON DELETE RESTRICT, "productName" VARCHAR(160) NOT NULL, "unitPrice" INTEGER NOT NULL CHECK ("unitPrice" >= 0), "quantity" INTEGER NOT NULL CHECK ("quantity" > 0));
CREATE TABLE "InventoryMovement" ("id" UUID PRIMARY KEY, "productId" UUID NOT NULL REFERENCES "Product"("id") ON DELETE RESTRICT, "orderId" UUID REFERENCES "Order"("id") ON DELETE RESTRICT, "quantityChange" INTEGER NOT NULL CHECK ("quantityChange" <> 0), "reason" "InventoryReason" NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "User_role_idx" ON "User"("role"); CREATE INDEX "Session_userId_idx" ON "Session"("userId"); CREATE INDEX "Session_expiresAt_idx" ON "Session"("expiresAt");
CREATE INDEX "Product_categoryId_isActive_idx" ON "Product"("categoryId", "isActive"); CREATE INDEX "Product_name_idx" ON "Product"("name"); CREATE INDEX "Product_stock_idx" ON "Product"("stock"); CREATE INDEX "CartItem_userId_idx" ON "CartItem"("userId");
CREATE INDEX "Order_userId_createdAt_idx" ON "Order"("userId", "createdAt" DESC); CREATE INDEX "Order_status_createdAt_idx" ON "Order"("status", "createdAt" DESC); CREATE INDEX "OrderItem_orderId_idx" ON "OrderItem"("orderId"); CREATE INDEX "OrderItem_productId_idx" ON "OrderItem"("productId"); CREATE INDEX "InventoryMovement_productId_createdAt_idx" ON "InventoryMovement"("productId", "createdAt" DESC); CREATE INDEX "InventoryMovement_orderId_idx" ON "InventoryMovement"("orderId");
